def update_testcase_duration(self, report):
    """accumulates total duration for nodeid from given report and updates
    the Junit.testcase with the new total if already created.
    """
    if self.report_duration == "total" or report.when == self.report_duration:
        reporter = self.node_reporter(report)
        reporter.duration += getattr(report, "duration", 0.0)

def pytest_collectreport(self, report):
    if not report.passed:
        reporter = self._opentestcase(report)
        if report.failed:
            reporter.append_collect_error(report)
        else:
            reporter.append_collect_skipped(report)

def pytest_internalerror(self, excrepr):
    reporter = self.node_reporter("internal")
    reporter.attrs.update(classname="pytest", name="internal")
    reporter._add_simple(Junit.error, "internal error", excrepr)

def pytest_sessionstart(self):
    self.suite_start_time = time.time()

def pytest_sessionfinish(self):
    dirname = os.path.dirname(os.path.abspath(self.logfile))
    if not os.path.isdir(dirname):
        os.makedirs(dirname)
    logfile = open(self.logfile, "w", encoding="utf-8")
    suite_stop_time = time.time()
    suite_time_delta = suite_stop_time - self.suite_start_time

    numtests = (
        self.stats["passed"]
        + self.stats["failure"]
        + self.stats["skipped"]
        + self.stats["error"]
        - self.cnt_double_fail_tests
    )
    logfile.write('<?xml version="1.0" encoding="utf-8"?>')

    suite_node = Junit.testsuite(
        self._get_global_properties_node(),
        [x.to_xml() for x in self.node_reporters_ordered],
        name=self.suite_name,
        errors=self.stats["error"],
        failures=self.stats["failure"],
        skipped=self.stats["skipped"],
        tests=numtests,
        time="%.3f" % suite_time_delta,
    )
    logfile.write(Junit.testsuites([suite_node]).unicode(indent=0))
    logfile.close()

def pytest_terminal_summary(self, terminalreporter):
    terminalreporter.write_sep("-", "generated xml file: %s" % (self.logfile))

def add_global_property(self, name, value):
    __tracebackhide__ = True
    _check_record_param_type("name", name)
    self.global_properties.append((name, bin_xml_escape(value)))

def _get_global_properties_node(self):
    """Return a Junit node containing custom properties, if any.
    """
    if self.global_properties:
        return Junit.properties(
            [
                Junit.property(name=name, value=value)
                for name, value in self.global_properties
            ]
        )
    return ""

import os
from xml.dom import minidom

import py

import pytest
from _pytest.junitxml import LogXML
from _pytest.reports import BaseReport


def runandparse(testdir, *args):
    resultpath = testdir.tmpdir.join("junit.xml")
    result = testdir.runpytest("--junitxml=%s" % resultpath, *args)
    xmldoc = minidom.parse(str(resultpath))
    return result, DomNode(xmldoc)


def assert_attr(node, **kwargs):
    __tracebackhide__ = True

    def nodeval(node, name):
        anode = node.getAttributeNode(name)
        if anode is not None:
            return anode.value

    expected = {name: str(value) for name, value in kwargs.items()}
    on_node = {name: nodeval(node, name) for name in expected}
    assert on_node == expected


class DomNode:
    def __init__(self, dom):
        self.__node = dom

    def __repr__(self):
        return self.__node.toxml()

    def find_first_by_tag(self, tag):
        return self.find_nth_by_tag(tag, 0)

    def _by_tag(self, tag):
        return self.__node.getElementsByTagName(tag)

    @property
    def children(self):
        return [type(self)(x) for x in self.__node.childNodes]

    @property
    def get_unique_child(self):
        children = self.children
        assert len(children) == 1
        return children[0]

    def find_nth_by_tag(self, tag, n):
        items = self._by_tag(tag)
        try:
            nth = items[n]
        except IndexError:
            pass
        else:
            return type(self)(nth)

    def find_by_tag(self, tag):
        t = type(self)
        return [t(x) for x in self.__node.getElementsByTagName(tag)]

    def __getitem__(self, key):
        node = self.__node.getAttributeNode(key)
        if node is not None:
            return node.value

    def assert_attr(self, **kwargs):
        __tracebackhide__ = True
        return assert_attr(self.__node, **kwargs)

    def toxml(self):
        return self.__node.toxml()

    @property
    def text(self):
        return self.__node.childNodes[0].wholeText

    @property
    def tag(self):
        return self.__node.tagName

    @property
    def next_sibling(self):
        return type(self)(self.__node.nextSibling)


class TestPython:
    def test_summing_simple(self, testdir):
        testdir.makepyfile(
            """
            import pytest
            def test_pass():
                pass
            def test_fail():
                assert 0
            def test_skip():
                pytest.skip("")
            @pytest.mark.xfail
            def test_xfail():
                assert 0
            @pytest.mark.xfail
            def test_xpass():
                assert 1
        """
        )
        result, dom = runandparse(testdir)
        assert result.ret
        node = dom.find_first_by_tag("testsuite")
        node.assert_attr(name="pytest", errors=0, failures=1, skipped=2, tests=5)

    def test_summing_simple_with_errors(self, testdir):
        testdir.makepyfile(
            """
            import pytest
            @pytest.fixture
            def fixture():
                raise Exception()
            def test_pass():
                pass
            def test_fail():
                assert 0
            def test_error(fixture):
                pass
            @pytest.mark.xfail
            def test_xfail():
                assert False
            @pytest.mark.xfail(strict=True)
            def test_xpass():
                assert True
        """
        )
        result, dom = runandparse(testdir)
        assert result.ret
        node = dom.find_first_by_tag("testsuite")
        node.assert_attr(name="pytest", errors=1, failures=2, skipped=1, tests=5)

    def test_timing_function(self, testdir):
        testdir.makepyfile(
            """
            import time, pytest
            def setup_module():
                time.sleep(0.01)
            def teardown_module():
                time.sleep(0.01)
            def test_sleep():
                time.sleep(0.01)
        """
        )
        result, dom = runandparse(testdir)
        node = dom.find_first_by_tag("testsuite")
        tnode = node.find_first_by_tag("testcase")
        val = tnode["time"]
        assert round(float(val), 2) >= 0.03

    @pytest.mark.parametrize("duration_report", ["call", "total"])
    def test_junit_duration_report(self, testdir, monkeypatch, duration_report):

        # mock LogXML.node_reporter so it always sets a known duration to each test report object
        original_node_reporter = LogXML.node_reporter

        def node_reporter_wrapper(s, report):
            report.duration = 1.0
            reporter = original_node_reporter(s, report)
            return reporter

        monkeypatch.setattr(LogXML, "node_reporter", node_reporter_wrapper)

        testdir.makepyfile(
            """
            def test_foo():
                pass
        """
        )
        result, dom = runandparse(
            testdir, "-o", "junit_duration_report={}".format(duration_report)
        )
        node = dom.find_first_by_tag("testsuite")
        tnode = node.find_first_by_tag("testcase")
        val = float(tnode["time"])
        if duration_report == "total":
            assert val == 3.0
        else:
            assert duration_report == "call"
            assert val == 1.0

    def test_setup_error(self, testdir):
        testdir.makepyfile(
            """
            import pytest

            @pytest.fixture
            def arg(request):
                raise ValueError()
            def test_function(arg):
                pass
        """
        )
        result, dom = runandparse(testdir)
        assert result.ret
        node = dom.find_first_by_tag("testsuite")
        node.assert_attr(errors=1, tests=1)
        tnode = node.find_first_by_tag("testcase")
        tnode.assert_attr(classname="test_setup_error", name="test_function")
        fnode = tnode.find_first_by_tag("error")
        fnode.assert_attr(message="test setup failure")
